INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('558294',2209,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Geração de Despesa e Despesa Obrigatória de Caráter Continuado (arts. 15 a 17 da LRF)','FAFIPA - Adv (CM Bandeir)/CM Bandeirantes (PR)/2016','Caderno Contabilidade Pública Parte 4','A lei de responsabilidade fiscal, de nº 101/2000, trata sobre a despesa obrigatória de caráter continuado no artigo 17. Desse modo, assinale a alternativa CORRETA.','[["A","Considera-se obrigatória de caráter continuado a despesa não corrente derivada de lei, medida provisória ou ato administrativo normativo que fixem para o ente a obrigação legal de sua execução por um período superior a um exercício."],["B","Considera-se obrigatória de caráter continuado a despesa não corrente derivada de lei, medida provisória ou ato administrativo normativo que fixem para o ente a obrigação legal de sua execução por um período superior a dois exercícios."],["C","Considera-se obrigatória de caráter continuado a despesa corrente derivada de lei, medida provisória ou ato administrativo normativo que fixem para o ente a obrigação legal de sua execução por um período superior a um exercício."],["D","Considera-se obrigatória de caráter continuado a despesa corrente derivada de lei, medida provisória ou ato administrativo normativo que fixem para o ente a obrigação legal de sua execução por um período superior a dois exercícios."]]'::jsonb,'D',2016,634,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Geração de Despesa e Despesa Obrigatória de Caráter Continuado (arts. 15 a 17 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Considera-se obrigatória de caráter continuado a despesa corrente derivada de lei, medida provisória ou ato administrativo normativo que fixem para o ente a obrigação legal de sua execução por um período superior a dois exercícios.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Geração de Despesa e Despesa Obrigatória de Caráter Continuado (arts. 15 a 17 da LRF)"}'::jsonb,'A lei de responsabilidade fiscal, de nº 101/2000, trata sobre a despesa obrigatória de caráter continuado no artigo 17. Desse modo, assinale a alternativa CORRETA.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('1061051',2210,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Geração de Despesa e Despesa Obrigatória de Caráter Continuado (arts. 15 a 17 da LRF)','FAFIPA - ALeg I (CM Foz do Iguaçu)/CM Foz do Iguaçu/2012','Caderno Contabilidade Pública Parte 4','De acordo com o que expressamente dispõe a Lei Complementar nº 101/2000 (Lei de Responsabilidade Fiscal), considera-se obrigatória de caráter continuado','[["A","a despesa corrente derivada de decreto legislativo que fixem para o ente a obrigação legal de sua execução por um período superior a uma legislatura."],["B","a despesa corrente que fixe para o ente a obrigação legal de sua execução por um período superior a um exercício."],["C","a despesa corrente derivada de decreto legislativo que fixem para o ente a obrigação legal de sua execução por um período superior a dois exercícios."],["D","a despesa corrente derivada de lei, medida provisória ou ato administrativo normativo que fixem para o ente a obrigação legal de sua execução por um período superior a dois meses."],["E","a despesa corrente derivada de lei, medida provisória ou ato administrativo normativo que fixem para o ente a obrigação legal de sua execução por um período superior a dois exercícios."]]'::jsonb,'E',2012,635,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Geração de Despesa e Despesa Obrigatória de Caráter Continuado (arts. 15 a 17 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — a despesa corrente derivada de lei, medida provisória ou ato administrativo normativo que fixem para o ente a obrigação legal de sua execução por um período superior a dois exercícios.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Geração de Despesa e Despesa Obrigatória de Caráter Continuado (arts. 15 a 17 da LRF)"}'::jsonb,'De acordo com o que expressamente dispõe a Lei Complementar nº 101/2000 (Lei de Responsabilidade Fiscal), considera-se obrigatória de caráter continuado') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('1061263',2211,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Geração de Despesa e Despesa Obrigatória de Caráter Continuado (arts. 15 a 17 da LRF)','FAFIPA - AContI (CM Foz do Iguaçu)/CM Foz do Iguaçu/2012','Caderno Contabilidade Pública Parte 4','Segundo o art. 17 da lei complementar 101/00, o que considera-se aumento de despesas?','[["A","Considera-se aumento de despesa o aumento discriminado de tributos ou contribuições, e outros benefícios que correspondam a tratamento diferenciado."],["B","Considera-se aumento de despesa a prorrogação daquela criada por prazo determinado."],["C","Considera-se aumento de despesa a efetiva arrecadação de todos os tributos da competência constitucional do ente da Federação."],["D","Considera-se aumento de despesa o cancelamento de débito cujo montante seja inferior ao dos respectivos custos de cobrança."],["E","Considera-se aumento de despesa a concessão ou ampliação de incentivo ou benefício, de natureza tributária, da qual decorra a estimativa do impacto orçamentário-financeiro no exercício em que deva iniciar sua vigência."]]'::jsonb,'B',2012,636,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Geração de Despesa e Despesa Obrigatória de Caráter Continuado (arts. 15 a 17 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — Considera-se aumento de despesa a prorrogação daquela criada por prazo determinado.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Geração de Despesa e Despesa Obrigatória de Caráter Continuado (arts. 15 a 17 da LRF)"}'::jsonb,'Segundo o art. 17 da lei complementar 101/00, o que considera-se aumento de despesas?') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3936163',2212,76,'P2','AFO, Direito Financeiro e Contabilidade Pública - Escrituração Contábil Pública','FAFIPA - PSP (SESA PR)/SESA PR/Contador/2026','Caderno Contabilidade Pública Parte 4','A Secretaria de Estado da Saúde recebeu, em julho de 2025, uma transferência financeira obrigatória do Fundo Nacional de Saúde, na modalidade fundo a fundo, destinada ao custeio de procedimentos de alta complexidade. Considerando o Plano de Contas Aplicado ao Setor Público (PCASP), assinale a alternativa que apresenta o lançamento contábil CORRETO para o reconhecimento dessa receita sob a Natureza de Informação Patrimonial.','[["A","Débito em Caixa e Equivalentes de Caixa / Crédito em Transferências Voluntárias."],["B","Débito em Caixa e Equivalentes de Caixa / Crédito em Transferências Constitucionais e Legais de Receitas."],["C","Débito em Transferências Constitucionais e Legais de Receitas / Crédito em Caixa e Equivalentes de Caixa."],["D","Débito em Caixa e Equivalentes de Caixa / Crédito em Impostos, Taxas e Contribuições de Melhoria."],["E","Débito em Transferências a Receber / Crédito em Transferências Constitucionais e Legais de Receitas."]]'::jsonb,'B',2026,637,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Escrituração Contábil Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — Débito em Caixa e Equivalentes de Caixa / Crédito em Transferências Constitucionais e Legais de Receitas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Escrituração Contábil Pública"}'::jsonb,'A Secretaria de Estado da Saúde recebeu, em julho de 2025, uma transferência financeira obrigatória do Fundo Nacional de Saúde, na modalidade fundo a fundo, destinada ao custeio de procedimentos de alta complexidade. Considerando o Plano de Contas Aplicado ao Setor Público (PCASP), assinale a alternativa que apresenta o lançamento contábil CORRETO para o reconhecimento dessa re') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4098485',2213,76,'P2','AFO, Direito Financeiro e Contabilidade Pública - Escrituração Contábil Pública','FAFIPA - Ana (CRC PR)/CRC PR/Contábil/2026','Caderno Contabilidade Pública Parte 4','O reconhecimento das variações patrimoniais e a correta mensuração do Resultado Patrimonial são essenciais para evidenciar a real situação econômica de uma entidade do setor público. Considerando os preceitos do regime de competência (enfoque patrimonial) e a estruturação do patrimônio público, julgue verdadeiro (V) ou falso (F) o que se afirma a seguir e assinale a alternativa com a sequência CORRETA. ( ) O recebimento de um imóvel em doação para uso nas atividades operacionais da entidade representa uma variação patrimonial qualitativa, uma vez que altera a composição do ativo imobilizado sem transitar pela execução orçamentária, mantendo o Patrimônio Líquido inalterado. ( ) A apropriação mensal da folha de pagamento dos servidores, ainda que o respectivo desembolso financeiro ocorra apenas no mês seguinte, gera uma Variação Patrimonial Diminutiva (VPD) que reduz o Patrimônio Líquido no momento da ocorrência do fato gerador. ( ) Considere que uma autarquia apresentou os seguintes dados no exercício: R$ 500.000,00 de tributos lançados; R$ 350.000,00 de tributos efetivamente arrecadados; R$ 200.000,00 de folha de pagamento apropriada (integralmente paga); e R$ 40.000,00 de depreciação de bens. O Resultado Patrimonial apurado no período foi um superávit de R$ 110.000,00, valor obtido pela diferença entre a arrecadação efetiva e as despesas consumidas. ( ) O reconhecimento do direito a receber decorrente do lançamento de um tributo gera uma Variação Patrimonial Aumentativa (VPA) no momento do fato gerador, independentemente da efetiva arrecadação financeira, em estrita observância ao regime de competência. ( ) O pagamento de uma obrigação passiva (como o repasse a fornecedores ou quitação de salários a pagar) reconhecida em um período anterior constitui um fato permutativo, ou seja, uma variação patrimonial qualitativa que não afeta o resultado patrimonial no momento da saída do recurso financeiro.','[["A","F, V, V, F, V."],["B","F, V, F, V, V."],["C","V, F, V, V, F."],["D","F, F, V, V, V."],["E","V, V, F, F, V."]]'::jsonb,'B',2026,638,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Escrituração Contábil Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — F, V, F, V, V.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Escrituração Contábil Pública"}'::jsonb,'O reconhecimento das variações patrimoniais e a correta mensuração do Resultado Patrimonial são essenciais para evidenciar a real situação econômica de uma entidade do setor público. Considerando os preceitos do regime de competência (enfoque patrimonial) e a estruturação do patrimônio público, julgue verdadeiro (V) ou falso (F) o que se afirma a seguir e assinale a alternativa') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3598423',2214,75,'P2','AFO, Direito Financeiro e Contabilidade Pública - Escrituração Contábil Pública','FAFIPA - Cont (Pref Franc Beltrão)/Pref Franc Beltrão/2025','Caderno Contabilidade Pública Parte 4','Com base no Manual de Contabilidade Aplicada ao Setor Público (MCASP) e na Lei nº 4.320/1964, avalie as afirmativas a seguir. I. A aquisição de cadeiras giratórias para a Secretaria de Educação deve ser registrada como material permanente, pois são bens com durabilidade superior a dois anos e que mantêm sua identidade física. II. A compra de toners para impressoras deve ser registrada como material permanente, uma vez que são utilizados com recorrência e relacionados a equipamentos duráveis. III. A compra de álcool em gel para uso interno das repartições deve ser classificada como material de consumo, pois se deteriora rapidamente com o uso. IV. A aquisição de placas de memória RAM para substituição em computadores com capacidade inferior à nova deve ser classificada como investimento (despesa de capital), por representar uma melhoria que aumenta a capacidade do bem. Está CORRETO o que se afirma em:','[["A","I, II, III e IV."],["B","I, III e IV, apenas."],["C","I e III, apenas."],["D","I, II e III, apenas."]]'::jsonb,'B',2025,639,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Escrituração Contábil Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — I, III e IV, apenas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Escrituração Contábil Pública"}'::jsonb,'Com base no Manual de Contabilidade Aplicada ao Setor Público (MCASP) e na Lei nº 4.320/1964, avalie as afirmativas a seguir. I. A aquisição de cadeiras giratórias para a Secretaria de Educação deve ser registrada como material permanente, pois são bens com durabilidade superior a dois anos e que mantêm sua identidade física. II. A compra de toners para impressoras deve ser reg') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('2715326',2215,73,'P2','AFO, Direito Financeiro e Contabilidade Pública - Escrituração Contábil Pública','FAFIPA - Cont (CM Nova Fátima (PR))/CM Nova Fátima (PR)/2023','Caderno Contabilidade Pública Parte 4','Imagine que em 20/01/2023 o Poder Executivo de Sabiá repassa o duodécimo a que a Câmara Municipal tem direito conforme as regras constitucionais, no valor de R$ 80.000,00. No momento do recebimento, sabendo que o Poder Legislativo não havia reconhecido antecipadamente seu direito no Balanço Patrimonial, indique qual seria a correta contabilização do fato, nas contas de natureza patrimonial, de acordo com o Plano de Contas Aplicado ao Setor Público.','[["A","D - 7.x.x.x.x.xx.xx Direitos Contratuais C - 8.x.x.x.x.xx.xx Execução de Direitos Contratuais...R$ 80.000,00"],["B","D - 1.x.x.x.x.xx.xx Caixa e Equivalentes de Caixa C - 4.x.x.x.x.xx.xx Transferências Intragovernamentais...R$ 80.000,00"],["C","D - 1.x.x.x.x.xx.xx Caixa e Equivalentes de Caixa C - 6.x.x.x.x.xx.xx Transferências Intragovernamentais...R$ 80.000,00"],["D","D - 1.x.x.x.x.xx.xx Caixa e Equivalentes de Caixa C - 6.x.x.x.x.xx.xx Receita Realizada...R$ 80.000,00"],["E","D - 4.x.x.x.x.xx.xx Transferências Intragovernamentais C - 1.x.x.x.x.xx.xx Caixa e Equivalentes de Caixa...R$ 80.000,00"]]'::jsonb,'B',2023,640,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Escrituração Contábil Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — D - 1.x.x.x.x.xx.xx Caixa e Equivalentes de Caixa C - 4.x.x.x.x.xx.xx Transferências Intragovernamentais...R$ 80.000,00","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Escrituração Contábil Pública"}'::jsonb,'Imagine que em 20/01/2023 o Poder Executivo de Sabiá repassa o duodécimo a que a Câmara Municipal tem direito conforme as regras constitucionais, no valor de R$ 80.000,00. No momento do recebimento, sabendo que o Poder Legislativo não havia reconhecido antecipadamente seu direito no Balanço Patrimonial, indique qual seria a correta contabilização do fato, nas contas de natureza') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('927061',2216,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Escrituração Contábil Pública','FAFIPA - Con (CM Paranapoema)/CM Paranapoema/2014','Caderno Contabilidade Pública Parte 4','De acordo com a Escrituração e Consolidação das Contas prevista na Lei Complementar n°. 101/00 das finanças públicas voltadas para a responsabilidade na gestão fiscal, assinale “V” para Verdadeiro ou “F” para Falso: ( ) A disponibilidade de caixa será demonstrado em registro sintético, de modo que os recursos fiquem demonstrados de forma resumida. É facultativa a escrituração de forma individualizada. ( ) A despesa e a assunção de compromisso serão registradas segundo o regime de caixa, apurando-se, em caráter complementar, o resultado dos fluxos financeiros pelo regime de competência. ( ) As receitas e despesas previdenciárias serão apresentadas em demonstrativos financeiros e orçamentários específicos. ( ) A demonstração das variações patrimoniais dará destaque à origem e ao destino dos recursos provenientes da alienação de ativos. Após classificar as afirmativas, assinale a alternativa que contém a sequência CORRETA, de cima para baixo:','[["A","V, V, F, F"],["B","V, F, V, F"],["C","F, F, V, V"],["D","F, V, F, V"]]'::jsonb,'C',2014,641,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Escrituração Contábil Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — F, F, V, V","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Escrituração Contábil Pública"}'::jsonb,'De acordo com a Escrituração e Consolidação das Contas prevista na Lei Complementar n°. 101/00 das finanças públicas voltadas para a responsabilidade na gestão fiscal, assinale “V” para Verdadeiro ou “F” para Falso: ( ) A disponibilidade de caixa será demonstrado em registro sintético, de modo que os recursos fiquem demonstrados de forma resumida. É facultativa a escrituração d') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('926998',2217,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Escrituração Contábil Pública','FAFIPA - Cont (CM Paranacity)/CM Paranacity/2012','Caderno Contabilidade Pública Parte 4','Conforme estabelece a Lei Complementar n° 101 de 4 de Maio de 2000 em seu art. 50, a Escrituração e Consolidação das Contas devem obedecer às demais normas de contabilidade pública. Marque a alternativa CORRETA que explica os critérios de escrituração das contas públicas: I. A disponibilidade de caixa não constará de registro próprio, de modo que os recursos vinculados a órgão, fundo ou despesa obrigatória fiquem identificados e escriturados de forma consolidada. II. A despesa e a assunção de compromisso serão registradas segundo o regime de caixa, apurando-se, em caráter complementar, o resultado dos fluxos financeiros pelo regime de competência. III. As demonstrações contábeis compreenderão, isolada e conjuntamente, as transações e operações De cada órgão, fundo ou entidade da administração direta, autárquica e fundacional, inclusive empresa Estatal dependente. IV. As receitas e despesas previdenciárias serão apresentadas em demonstrativos financeiros e orçamentários específicos. V. As operações de crédito, as inscrições em restos a pagar e as demais formas de financiamento ou Assunção de compromissos junto a terceiros, deverão ser escrituradas de modo a evidenciar o montante e a variação da dívida pública no período, detalhando, pelo menos, a natureza e o tipo de credor.','[["A","As afirmativas I, II e III estão incorretas."],["B","As afirmativas I, II e III estão corretas."],["C","As afirmativas II, III e IV estão corretas."],["D","As afirmativas III, IV e V estão corretas."],["E","As afirmativas III, IV e V estão incorretas."]]'::jsonb,'D',2012,642,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Escrituração Contábil Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — As afirmativas III, IV e V estão corretas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Escrituração Contábil Pública"}'::jsonb,'Conforme estabelece a Lei Complementar n° 101 de 4 de Maio de 2000 em seu art. 50, a Escrituração e Consolidação das Contas devem obedecer às demais normas de contabilidade pública. Marque a alternativa CORRETA que explica os critérios de escrituração das contas públicas: I. A disponibilidade de caixa não constará de registro próprio, de modo que os recursos vinculados a órgão,') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3339308',2218,75,'P2','AFO, Direito Financeiro e Contabilidade Pública - Normas Gerais de Direito Financeiro','FAFIPA - Proc Mun (Pref Araucária)/Pref Araucária/2025','Caderno Contabilidade Pública Parte 4','O Direito Financeiro, assim como os demais ramos do Direito, tem princípios relacionados às normas gerais e aos valores e fundamentos da atividade financeira do Estado. Sobre os princípios do Direito Financeiro, julgue verdadeiro (V) ou falso (F) o que se afirma a seguir e assinale a alternativa com a sequência CORRETA. (__) O princípio da justiça fiscal objetiva a promoção da redução da desigualdade por meio da distribuição de riqueza, inclusive tendo como fundamento outro princípio constitucional previsto no artigo 5º: o princípio da igualdade. (__) O princípio da organicidade não permite que seja inserido no corpo da Lei Orçamentária Anual qualquer dispositivo estranho à previsão de receitas públicas, despesas públicas, operações de créditos e aberturas de créditos adicionais. (__) O princípio da economia determina a devida discriminação de todas as receitas e despesas, não podendo ser lançadas de forma genérica. (__) O princípio da solidariedade refere-se à aplicação de receitas públicas de forma diferenciada entre os grupos sociais. Isso é feito por meio da arrecadação dessas receitas junto à sociedade, especialmente na forma de tributos.','[["A","F, F, F, V."],["B","V, F, V, F."],["C","V, F, F, V."],["D","V, V, F, F."],["E","F, F, V, V."]]'::jsonb,'C',2025,643,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Normas Gerais de Direito Financeiro.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — V, F, F, V.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Normas Gerais de Direito Financeiro"}'::jsonb,'O Direito Financeiro, assim como os demais ramos do Direito, tem princípios relacionados às normas gerais e aos valores e fundamentos da atividade financeira do Estado. Sobre os princípios do Direito Financeiro, julgue verdadeiro (V) ou falso (F) o que se afirma a seguir e assinale a alternativa com a sequência CORRETA. (__) O princípio da justiça fiscal objetiva a promoção da ') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('2416316',2219,73,'P2','AFO, Direito Financeiro e Contabilidade Pública - Normas Gerais de Direito Financeiro','FAFIPA - Tec Cont (FAZPREV)/FAZPREV/Administrativo/2023','Caderno Contabilidade Pública Parte 4','O tipo de lei que disporá sobre finanças públicas:','[["A","Lei Resolutiva."],["B","Lei Ordinária."],["C","Lei Delegada."],["D","Medida Provisória."],["E","Lei Complementar."]]'::jsonb,'E',2023,644,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Normas Gerais de Direito Financeiro.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — Lei Complementar.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Normas Gerais de Direito Financeiro"}'::jsonb,'O tipo de lei que disporá sobre finanças públicas:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3023786',2220,73,'P2','AFO, Direito Financeiro e Contabilidade Pública - Normas Gerais de Direito Financeiro','FAFIPA - Ana Cont (CRJ)/CRJ/2022','Caderno Contabilidade Pública Parte 4','O orçamento público está amparado na Constituição Federal nos art. 165 a 169, nestes artigos estabelecem o Sistema Orçamentário. Marque a alternativa CORRETA, "Estabelecer normas de gestão financeira e patrimonial da administração direta e indireta, bem como condições para a instituição''''. Cabe:','[["A","a medidas provisórias."],["B","à lei delegada."],["C","à lei complementar."],["D","à lei ordinária."],["E","a decretos legislativos."]]'::jsonb,'C',2022,645,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Normas Gerais de Direito Financeiro.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — à lei complementar.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Normas Gerais de Direito Financeiro"}'::jsonb,'O orçamento público está amparado na Constituição Federal nos art. 165 a 169, nestes artigos estabelecem o Sistema Orçamentário. Marque a alternativa CORRETA, "Estabelecer normas de gestão financeira e patrimonial da administração direta e indireta, bem como condições para a instituição''''. Cabe:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('563072',2221,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Normas Gerais de Direito Financeiro','FAFIPA - Proc J (CM Cambará)/CM Cambará/2016','Caderno Contabilidade Pública Parte 4','Dadas as assertivas abaixo, assinale a alternativa CORRETA. I. O direito financeiro tem por objetivo disciplinar a atividade financeira do Estado e, assim, estabelecer regras relativas aos três pilares dessa atividade: o orçamento público, a receita pública e a despesa pública. II. O princípio da econominicade é um dos princípios do direito financeiro, estando enunciado no artigo 70, caput, da Constituição Federal. Este princípio é relativo à exigência de eficiência, do ponto de vista político, do gasto público: com o máximo de recursos possíveis, deve-se atingir o máximo de satisfação das necessidades públicas. III. Nos termos do art. 24, I, da Constituição Federal, compete à União, aos Estados e ao Distrito Federal legislar concorrentemente sobre o direito financeiro. IV. A União ficará adstrita à criação de normas gerais de direito financeiro. Caso a União não estabeleça normas gerais, os Estados e o Distrito Federal exercerão competência legislativa plena, para atender às suas peculiaridades e o advento posterior de norma geral da União invalidade completamente a lei estadual.','[["A","Todas estão corretas."],["B","Todas estão incorretas."],["C","Somente II e III estão corretas."],["D","Somente II e IV estão incorretas."]]'::jsonb,'D',2016,646,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Normas Gerais de Direito Financeiro.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Somente II e IV estão incorretas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Normas Gerais de Direito Financeiro"}'::jsonb,'Dadas as assertivas abaixo, assinale a alternativa CORRETA. I. O direito financeiro tem por objetivo disciplinar a atividade financeira do Estado e, assim, estabelecer regras relativas aos três pilares dessa atividade: o orçamento público, a receita pública e a despesa pública. II. O princípio da econominicade é um dos princípios do direito financeiro, estando enunciado no arti') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('923528',2222,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Normas Gerais de Direito Financeiro','FAFIPA - OfAd (CM Campina GS)/CM Campina G do Sul/2014','Caderno Contabilidade Pública Parte 4','A contabilidade é a ferramenta de controle e planejamento administrativo. Assinale a alternativa CORRETA sobre a regulamentação legal que rege a contabilidade pública:','[["A","Lei Federal 8.159/91 e Constituição Federal de 1988, art.166."],["B","Lei Federal 4.320/64, Lei Complementar 101/2000 e Constituição Federal/1988, Art. 165."],["C","Lei Federal 4117/1962 e CF/88, art.150."],["D","Lei Federal no. 1040/1969."]]'::jsonb,'B',2014,647,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Normas Gerais de Direito Financeiro.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — Lei Federal 4.320/64, Lei Complementar 101/2000 e Constituição Federal/1988, Art. 165.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Normas Gerais de Direito Financeiro"}'::jsonb,'A contabilidade é a ferramenta de controle e planejamento administrativo. Assinale a alternativa CORRETA sobre a regulamentação legal que rege a contabilidade pública:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=