INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('2414142',2223,73,'P2','AFO, Direito Financeiro e Contabilidade Pública - Demais Temas de Contabilidade Pública','FAFIPA - Cont (CODUSA)/CODUSA/2022','Caderno Contabilidade Pública Parte 4','De acordo com a NBC TP 01 (R1), de 19/03/2020, item 2, o conceito de perito é o contador detentor de conhecimento técnico e científico, regularmente registrado em Conselho Regional de Contabilidade e no Cadastro Nacional dos Peritos Contábeis, que exerce a atividade pericial de forma pessoal ou por meio de órgão técnico ou científico. Considerando e interpretando estritamente o exposto, assinale a alternativa CORRETA:','[["A","O perito contábil deve obrigatoriamente fazer parte de órgão técnico ou científico."],["B","O perito contábil pode fazer parte de órgão técnico ou científico."],["C","O perito contábil não pode fazer parte de órgão técnico ou científico."],["D","Nenhuma das alternativas."]]'::jsonb,'B',2022,648,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Demais Temas de Contabilidade Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — O perito contábil pode fazer parte de órgão técnico ou científico.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Demais Temas de Contabilidade Pública"}'::jsonb,'De acordo com a NBC TP 01 (R1), de 19/03/2020, item 2, o conceito de perito é o contador detentor de conhecimento técnico e científico, regularmente registrado em Conselho Regional de Contabilidade e no Cadastro Nacional dos Peritos Contábeis, que exerce a atividade pericial de forma pessoal ou por meio de órgão técnico ou científico. Considerando e interpretando estritamente o') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('2414143',2224,73,'P2','AFO, Direito Financeiro e Contabilidade Pública - Demais Temas de Contabilidade Pública','FAFIPA - Cont (CODUSA)/CODUSA/2022','Caderno Contabilidade Pública Parte 4','De acordo com a NBC TP 01 (R1), de 19/03/2020, item 3, o laudo pericial contábil tem o que por limite o objeto da perícia deferida ou contratada. Considerando e interpretando estritamente o exposto, assinale a alternativa CORRETA:','[["A","Nenhuma das alternativas."],["B","O perito nunca deve se limitar ao objeto da perícia deferida ou contratada."],["C","O perito não deve se limitar ao objeto da perícia deferida ou contratada."],["D","O perito deve se limitar ao objeto da perícia deferida ou contratada."]]'::jsonb,'D',2022,649,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Demais Temas de Contabilidade Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — O perito deve se limitar ao objeto da perícia deferida ou contratada.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Demais Temas de Contabilidade Pública"}'::jsonb,'De acordo com a NBC TP 01 (R1), de 19/03/2020, item 3, o laudo pericial contábil tem o que por limite o objeto da perícia deferida ou contratada. Considerando e interpretando estritamente o exposto, assinale a alternativa CORRETA:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('2414144',2225,73,'P2','AFO, Direito Financeiro e Contabilidade Pública - Demais Temas de Contabilidade Pública','FAFIPA - Cont (CODUSA)/CODUSA/2022','Caderno Contabilidade Pública Parte 4','De acordo com a NBC TP 01 (R1), de 19/03/2020, item 17, o termo de diligência serve para formalizar e comprovar o trabalho de campo; deve ser redigido pelo perito nomeado; e ser encaminhado ao diligenciado. Considerando e interpretando estritamente o exposto, assinale a alternativa CORRETA:','[["A","O termo de diligência nunca deve ser encaminhado diretamente ao diligenciado."],["B","O termo de diligência deve ser encaminhado diretamente ao diligenciado."],["C","Nenhuma das alternativas."],["D","O termo de diligência não deve ser encaminhado diretamente ao diligenciado."]]'::jsonb,'B',2022,650,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Demais Temas de Contabilidade Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — O termo de diligência deve ser encaminhado diretamente ao diligenciado.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Demais Temas de Contabilidade Pública"}'::jsonb,'De acordo com a NBC TP 01 (R1), de 19/03/2020, item 17, o termo de diligência serve para formalizar e comprovar o trabalho de campo; deve ser redigido pelo perito nomeado; e ser encaminhado ao diligenciado. Considerando e interpretando estritamente o exposto, assinale a alternativa CORRETA:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('635040',2226,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Demais Temas de Contabilidade Pública','FAFIPA - Cont (CM BV Paraíso)/CM BV Paraíso/2016','Caderno Contabilidade Pública Parte 4','Os aspectos da contabilidade aplicada ao Setor Público previstos no Manual de Contabilidade Aplicada ao Setor Público – MCASP estabelecem que: I. A apuração e evidenciação, por meio da contabilidade, dos indicadores estabelecidos pela Lei de Responsabilidade Fiscal – LRF, dentre os quais se destacam os da despesa com pessoal, das operações de crédito e da dívida consolidada, além da apuração da disponibilidade de caixa, do resultado primário e do resultado nominal, a fim de verificar-se o equilíbrio das contas públicas. II. O Relatório de Gestão Fiscal (RGF) e o Relatório Resumido da Execução Orçamentária (RREO) representam os principais instrumentos para evidenciar esse aspecto. As características apresentadas acima refletem o aspecto:','[["A","Patrimonial."],["B","Orçamentário."],["C","Fiscal."],["D","Financeiro."]]'::jsonb,'C',2016,651,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Demais Temas de Contabilidade Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — Fiscal.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Demais Temas de Contabilidade Pública"}'::jsonb,'Os aspectos da contabilidade aplicada ao Setor Público previstos no Manual de Contabilidade Aplicada ao Setor Público – MCASP estabelecem que: I. A apuração e evidenciação, por meio da contabilidade, dos indicadores estabelecidos pela Lei de Responsabilidade Fiscal – LRF, dentre os quais se destacam os da despesa com pessoal, das operações de crédito e da dívida consolidada, al') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('942412',2227,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Demais Temas de Contabilidade Pública','FAFIPA - Cont (CIPS)/CIPS/2013','Caderno Contabilidade Pública Parte 4','Com relação às Normas Gerais de Consolidação das contas dos Consórcios Públicos, previstas na Portaria n° 72, de 01 de Fevereiro de 2012, assinale a alternativa INCORRETA sobre a Contabilidade Patrimonial e a Transparência do Consórcio Público:','[["A","A transferência de bens por parte dos entes consorciados, inclusive sob a forma de doação e de recursos em virtude de contrato de rateio será registrada, do ponto de vista patrimonial, como aumento de participação no consórcio público."],["B","Os entes da Federação consorciados evidenciarão sua participação no consórcio público em seu balanço patrimonial como passivo não circulante – investimentos, devidamente atualizados por método de custos."],["C","Dar ampla divulgação, inclusive em meio eletrônico de acesso público, aos seguintes documentos: o orçamento do consórcio público; o contrato de rateio; as demonstrações contábeis previstas nas normas gerais de direito financeiro e sua regulamentação."],["D","Divulgar os relatórios de Gestão Fiscal: Demonstrativo da Despesa com Pessoal; Demonstrativo da Disponibilidade de Caixa; e Demonstrativo dos Restos a Pagar."],["E","Divulgar os relatórios Resumidos da Execução Orçamentária: Balanço Orçamentário; Demonstrativo da Execução das Despesas por Função e Sub-Função."]]'::jsonb,'B',2013,652,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Demais Temas de Contabilidade Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — Os entes da Federação consorciados evidenciarão sua participação no consórcio público em seu balanço patrimonial como passivo não circulante – investimentos, devidamente atualizados por método de custos.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Demais Temas de Contabilidade Pública"}'::jsonb,'Com relação às Normas Gerais de Consolidação das contas dos Consórcios Públicos, previstas na Portaria n° 72, de 01 de Fevereiro de 2012, assinale a alternativa INCORRETA sobre a Contabilidade Patrimonial e a Transparência do Consórcio Público:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3710444',2228,75,'P2','AFO, Direito Financeiro e Contabilidade Pública - Vedações Constitucionais em Matéria Orçamentária (Art. 167 da CF/1988)','FAFIPA - Ag FT (Pref Jaguapitã)/Pref Jaguapitã/2025','Caderno Contabilidade Pública Parte 4','Considere as seguintes situações sobre finanças públicas. Situação I – A Prefeitura iniciou a construção de uma nova escola sem que o projeto constasse na Lei Orçamentária Anual, alegando tratar-se de prioridade política do gestor. Situação II – O Tesouro Municipal utilizou parte da arrecadação de impostos para repassar recursos diretamente à associação de servidores, com a finalidade de custear despesas administrativas internas. Situação III – O Executivo abriu crédito suplementar com autorização da Câmara de Vereadores indicou a fonte de recursos proveniente do superávit financeiro do exercício anterior. Situação IV – A Secretaria da Fazenda realizou operação de crédito cujo valor total ultrapassava as despesas de capital, mas possuía autorização legislativa específica para financiar projeto de saneamento básico. Situação V – O Prefeito criou um fundo municipal para investimentos em inovação tecnológica, sem li específica que o instituísse, mas com previsão genérica na lei de diretrizes orçamentárias. Com base na Constituição Federal, assinale a alternativa CORRETA.','[["A","As Situações I, III e V estão em plena conformidade com o texto constitucional, por se tratarem de atos discricionários do gestor público."],["B","Na Situação I e na Situação II, há afronta às vedações constitucionais de finanças públicas."],["C","Na Situação III e na Situação IV, ambas configuram violação às normas orçamentárias, pois exigem lei complementar para autorização."],["D","Apenas a Situação V está em conformidade com a Constituição, por envolver política pública de inovação prevista na lei de diretrizes orçamentárias."]]'::jsonb,'B',2025,653,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Vedações Constitucionais em Matéria Orçamentária (Art. 167 da CF/1988).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — Na Situação I e na Situação II, há afronta às vedações constitucionais de finanças públicas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Vedações Constitucionais em Matéria Orçamentária (Art. 167 da CF/1988)"}'::jsonb,'Considere as seguintes situações sobre finanças públicas. Situação I – A Prefeitura iniciou a construção de uma nova escola sem que o projeto constasse na Lei Orçamentária Anual, alegando tratar-se de prioridade política do gestor. Situação II – O Tesouro Municipal utilizou parte da arrecadação de impostos para repassar recursos diretamente à associação de servidores, com a fin') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3862424',2229,75,'P2','AFO, Direito Financeiro e Contabilidade Pública - Vedações Constitucionais em Matéria Orçamentária (Art. 167 da CF/1988)','FAFIPA - Cont (Pref Jundiaí do Sul)/Pref Jundiaí do Sul/2025','Caderno Contabilidade Pública Parte 4','Ao tratar do Orçamento, a Constituição Federal faz referência a várias vedações orçamentárias. Assinale a alternativa que NÃO corresponde a uma dessas vedações.','[["A","A realização de operações de créditos que excedam o montante das despesas de capital, ressalvadas as autorizadas mediante créditos suplementares ou especiais com finalidade precisa, aprovados pelo Poder Legislativo por maioria absoluta."],["B","A criação de fundo público, quando seus objetivos puderem ser alcançados mediante a vinculação de receitas orçamentárias específicas ou mediante a execução direta por programação orçamentária e financeira de órgão ou entidade da administração pública."],["C","A concessão ou utilização de créditos ilimitados."],["D","A transposição, o remanejamento ou a transferência de recursos de uma categoria de programação para outra ou de um órgão para outro, com prévia autorização legislativa."],["E","O início de programas ou projetos não incluídos na lei orçamentária anual."]]'::jsonb,'D',2025,654,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Vedações Constitucionais em Matéria Orçamentária (Art. 167 da CF/1988).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — A transposição, o remanejamento ou a transferência de recursos de uma categoria de programação para outra ou de um órgão para outro, com prévia autorização legislativa.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Vedações Constitucionais em Matéria Orçamentária (Art. 167 da CF/1988)"}'::jsonb,'Ao tratar do Orçamento, a Constituição Federal faz referência a várias vedações orçamentárias. Assinale a alternativa que NÃO corresponde a uma dessas vedações.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('2715298',2230,73,'P2','AFO, Direito Financeiro e Contabilidade Pública - Vedações Constitucionais em Matéria Orçamentária (Art. 167 da CF/1988)','FAFIPA - Cont (CM Nova Fátima (PR))/CM Nova Fátima (PR)/2023','Caderno Contabilidade Pública Parte 4','O ciclo orçamentário brasileiro obedece a disposições da Constituição Federal, dentre elas a conhecida "Regra de Ouro", insculpida no art. 167, III da CF/1988, a qual estabelece que é vedada:','[["A","a realização de receitas de capital que excedam o montante das despesas de capital, ressalvadas as autorizadas mediante créditos suplementares ou especiais com finalidade precisa, aprovados pelo Poder Legislativo por maioria absoluta."],["B","a realização de operações de créditos que excedam o montante dos investimentos, ressalvadas as autorizadas mediante créditos suplementares ou especiais com finalidade precisa, aprovados pelo Poder Legislativo por maioria absoluta."],["C","a realização de operações de créditos que excedam o montante das amortizações da dívida, ressalvadas as autorizadas mediante créditos suplementares ou especiais com finalidade precisa, aprovados pelo Poder Legislativo por maioria absoluta."],["D","a realização de inversões financeiras que excedam o montante das despesas de capital, ressalvadas as autorizadas mediante créditos suplementares ou especiais com finalidade precisa, aprovados pelo Poder Legislativo por maioria absoluta."],["E","a realização de operações de créditos que excedam o montante das despesas de capital, ressalvadas as autorizadas mediante créditos suplementares ou especiais com finalidade precisa, aprovados pelo Poder Legislativo por maioria absoluta."]]'::jsonb,'E',2023,655,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Vedações Constitucionais em Matéria Orçamentária (Art. 167 da CF/1988).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — a realização de operações de créditos que excedam o montante das despesas de capital, ressalvadas as autorizadas mediante créditos suplementares ou especiais com finalidade precisa, aprovados pelo Poder Legislativo por maioria absoluta.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Vedações Constitucionais em Matéria Orçamentária (Art. 167 da CF/1988)"}'::jsonb,'O ciclo orçamentário brasileiro obedece a disposições da Constituição Federal, dentre elas a conhecida "Regra de Ouro", insculpida no art. 167, III da CF/1988, a qual estabelece que é vedada:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3680437',2231,73,'P2','AFO, Direito Financeiro e Contabilidade Pública - Vedações Constitucionais em Matéria Orçamentária (Art. 167 da CF/1988)','FAFIPA - Cont (CM SJ Pinhais)/CM SJ dos Pinhais/2023','Caderno Contabilidade Pública Parte 4','A Constituição da República Federativa do Brasil estabelece importantes normas a serem observadas na elaboração e na execução dos Orçamentos. Uma delas, notoriamente conhecida como a "Regra de Ouro", estabelece que:','[["A","é vedada a realização de despesas de capital com recursos provenientes de receitas de operações descrédito, ressalvadas as autorizadas mediante créditos suplementares ou especiais com finalidade precisa, aprovados pelo Poder Legislativo por maioria absoluta.."],["B","é vedada a realização de operações de créditos para o financiamento de despesas correntes. Tal regranão admite qualquer tipo de exceção."],["C","é vedada a realização de operações de créditos que excedam o total do Ativo Não-Circulante do enteda Federação, salvo se aprovado por maioria absoluta do Poder Legislativo, e desde que destinada àaquisição de Ativo Não-Circulante.."],["D","é vedada a aplicação de recursos provenientes de receitas de capital em quaisquer tipos de despesacorrente, salvo se aprovado por maioria simples do Poder Legislativo.."],["E","é vedada a realização de operações de créditos que excedam o montante das despesas decapital, ressalvadas as autorizadas mediante créditos suplementares ou especiais comfinalidade precisa, aprovados pelo Poder Legislativo por maioria absoluta.."]]'::jsonb,'E',2023,656,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Vedações Constitucionais em Matéria Orçamentária (Art. 167 da CF/1988).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — é vedada a realização de operações de créditos que excedam o montante das despesas decapital, ressalvadas as autorizadas mediante créditos suplementares ou especiais comfinalidade precisa, aprovados pelo Poder Legislativo por maioria absoluta..","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Vedações Constitucionais em Matéria Orçamentária (Art. 167 da CF/1988)"}'::jsonb,'A Constituição da República Federativa do Brasil estabelece importantes normas a serem observadas na elaboração e na execução dos Orçamentos. Uma delas, notoriamente conhecida como a "Regra de Ouro", estabelece que:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('942402',2232,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Vedações Constitucionais em Matéria Orçamentária (Art. 167 da CF/1988)','FAFIPA - Cont (CIPS)/CIPS/2013','Caderno Contabilidade Pública Parte 4','A Constituição da República Federativa do Brasil de 1988 trata dos Orçamentos. Assinale a alternativa CORRETA que indica os vetos nos orçamentos de acordo com o art. 167: I. O início de programas ou projetos incluídos na lei orçamentária anual. II. A realização de despesas ou a assunção de obrigações diretas que excedam os créditos orçamentários ou adicionais. III. A realização de operações de créditos que excedam o montante das despesas de capital, ressalvadas as autorizadas mediante créditos suplementares ou especiais com finalidade precisa, aprovados pelo Poder Legislativo por maioria absoluta. IV. A abertura de crédito suplementar ou especial com prévia autorização legislativa e com indicação dos recursos correspondentes. V. A transposição, o remanejamento ou a transferência de recursos de uma categoria de programação para outra ou de um órgão para outro, sem prévia autorização legislativa.','[["A","As afirmativas I, II e III estão corretas."],["B","As afirmativas II, III e V estão corretas."],["C","As afirmativas III, IV e V estão corretas."],["D","Apenas as afirmativas II e III estão corretas."],["E","Apenas as afirmativas I e IV estão corretas."]]'::jsonb,'B',2013,657,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Vedações Constitucionais em Matéria Orçamentária (Art. 167 da CF/1988).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — As afirmativas II, III e V estão corretas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Vedações Constitucionais em Matéria Orçamentária (Art. 167 da CF/1988)"}'::jsonb,'A Constituição da República Federativa do Brasil de 1988 trata dos Orçamentos. Assinale a alternativa CORRETA que indica os vetos nos orçamentos de acordo com o art. 167: I. O início de programas ou projetos incluídos na lei orçamentária anual. II. A realização de despesas ou a assunção de obrigações diretas que excedam os créditos orçamentários ou adicionais. III. A realização') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('1058831',2233,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Controle da Gestão Fiscal (arts. 56 a 59 da LRF)','FAFIPA - Cont Jr (FC Foz)/FC Foz do Iguaçu/2019','Caderno Contabilidade Pública Parte 4','A Lei Complementar nº 101/2000 (Lei de Responsabilidade Fiscal) estabelece limites para os entes Federativos realizarem gastos com pessoal, prevendo ainda a possibilidade de aplicação de severas sanções em caso do descumprimento deste limite. Neste sentido, em relação à fiscalização da gestão fiscal, caso seja constatado pelo órgão fiscalizador que a despesa com pessoal de determinado ente público atinja o percentual de 92% do limite previsto:','[["A","O Ministério Público deverá julgar as contas deste ente público como irregulares."],["B","O Tribunal de Contas deverá julgar as contas deste ente público como irregulares."],["C","O Tribunal de Contas deverá alertar o ente público que a despesa com pessoal ultrapassou 90% (noventa por cento) do limite."],["D","O Ministério Público deverá abrir o procedimento de Tomada de Contas Especial para verificação acerca dos motivos que levaram a despesa com pessoal a este patamar."]]'::jsonb,'C',2019,658,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Controle da Gestão Fiscal (arts. 56 a 59 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — O Tribunal de Contas deverá alertar o ente público que a despesa com pessoal ultrapassou 90% (noventa por cento) do limite.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Controle da Gestão Fiscal (arts. 56 a 59 da LRF)"}'::jsonb,'A Lei Complementar nº 101/2000 (Lei de Responsabilidade Fiscal) estabelece limites para os entes Federativos realizarem gastos com pessoal, prevendo ainda a possibilidade de aplicação de severas sanções em caso do descumprimento deste limite. Neste sentido, em relação à fiscalização da gestão fiscal, caso seja constatado pelo órgão fiscalizador que a despesa com pessoal de dete') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('924018',2234,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Controle da Gestão Fiscal (arts. 56 a 59 da LRF)','FAFIPA - AIM (Pref Toledo (PR))/Pref Toledo (PR)/2016','Caderno Contabilidade Pública Parte 4','De acordo com a Lei Complementar nº 101/2000 (Lei de Responsabilidade Fiscal), quando o Poder Executivo ultrapassa 90% do limite estabelecido para a despesa total com pessoal, ele deve ser alertado pelo:','[["A","Tribunal de Contas."],["B","Departamento Contábil."],["C","Ministério Público."],["D","Poder Judiciário."],["E","Poder Legislativo."]]'::jsonb,'A',2016,659,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Controle da Gestão Fiscal (arts. 56 a 59 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — Tribunal de Contas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Controle da Gestão Fiscal (arts. 56 a 59 da LRF)"}'::jsonb,'De acordo com a Lei Complementar nº 101/2000 (Lei de Responsabilidade Fiscal), quando o Poder Executivo ultrapassa 90% do limite estabelecido para a despesa total com pessoal, ele deve ser alertado pelo:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3013732',2235,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Controle da Gestão Fiscal (arts. 56 a 59 da LRF)','FAFIPA - Tes (CM Nova Londrina)/CM Nova Londrina/2016','Caderno Contabilidade Pública Parte 4','Conforme estabelece a Fiscalização da Gestão Fiscal previsto na Lei de Responsabilidade Fiscal (LRF nº 101/2000), o Poder Legislativo, diretamente ou com o auxílio dos Tribunais de Contas, e o sistema de controle interno de cada Poder e do Ministério Público, fiscalizarão o cumprimento das normas desta Lei Complementar. Os Tribunais de Contas alertarão os Poderes ou órgãos referidos no art. 20 da LRF quando constatarem: I. Que o montante da despesa total com pessoal ultrapassou 90% (noventa por cento) do limite. II. Que os montantes das dívidas consolidada e mobiliária, das operações de crédito e da concessão de garantia se encontram acima de 90% (noventa por cento) dos respectivos limites. III. Que os gastos com inativos e pensionistas se encontram acima do limite definido em lei. IV. Fatos que comprometam os custos ou os resultados dos programas ou indícios de irregularidades na gestão orçamentária. Assinale a alternativa CORRETA.','[["A","Apenas as assertivas I e II estão incorretas."],["B","Apenas as assertivas III e IV estão incorretas."],["C","Apenas as assertivas I, III e IV estão corretas."],["D","Todas as assertivas estão corretas."]]'::jsonb,'D',2016,660,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Controle da Gestão Fiscal (arts. 56 a 59 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Todas as assertivas estão corretas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Controle da Gestão Fiscal (arts. 56 a 59 da LRF)"}'::jsonb,'Conforme estabelece a Fiscalização da Gestão Fiscal previsto na Lei de Responsabilidade Fiscal (LRF nº 101/2000), o Poder Legislativo, diretamente ou com o auxílio dos Tribunais de Contas, e o sistema de controle interno de cada Poder e do Ministério Público, fiscalizarão o cumprimento das normas desta Lei Complementar. Os Tribunais de Contas alertarão os Poderes ou órgãos refe') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('942407',2236,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Controle da Gestão Fiscal (arts. 56 a 59 da LRF)','FAFIPA - Cont (CIPS)/CIPS/2013','Caderno Contabilidade Pública Parte 4','De acordo com a Lei Complementar n° 101 de 4 de Maio de 2000, o Poder Legislativo, diretamente ou com o auxílio dos Tribunais de Contas, e o sistema de controle interno de cada Poder e do Ministério Público, fiscalizarão o cumprimento das normas desta Lei: I. Atingimento das metas estabelecidas na lei de diretrizes orçamentárias; II. Limites e condições para realização de operações de crédito e inscrição em Restos a Pagar; III. Medidas adotadas para o retorno da despesa total com pessoal ao respectivo limite, previstos nesta lei. IV. Destinação de recursos obtidos com a alienação de ativos, tendo em vista as restrições constitucionais e as desta Lei Complementar; V. Cumprimento do limite de gastos totais dos legislativos municipais, quando houver. Assinale a alternativa CORRETA.','[["A","Somente as afirmativas I e II são corretas."],["B","Somente as afirmativas I e IV são corretas."],["C","Somente as afirmativas III, IV e V são corretas."],["D","Somente as afirmativas I, II e III são corretas."],["E","Todas as afirmativas são corretas."]]'::jsonb,'E',2013,661,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Controle da Gestão Fiscal (arts. 56 a 59 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — Todas as afirmativas são corretas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Controle da Gestão Fiscal (arts. 56 a 59 da LRF)"}'::jsonb,'De acordo com a Lei Complementar n° 101 de 4 de Maio de 2000, o Poder Legislativo, diretamente ou com o auxílio dos Tribunais de Contas, e o sistema de controle interno de cada Poder e do Ministério Público, fiscalizarão o cumprimento das normas desta Lei: I. Atingimento das metas estabelecidas na lei de diretrizes orçamentárias; II. Limites e condições para realização de opera') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('1061390',2237,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Controle da Gestão Fiscal (arts. 56 a 59 da LRF)','FAFIPA - CTL I (CM Foz do Iguaçu)/CM Foz do Iguaçu/2012','Caderno Contabilidade Pública Parte 4','Analise as assertivas e assinale a alternativa que aponta as corretas. De acordo com a Lei de Responsabilidade Fiscal, o Poder Legislativo, diretamente ou com o auxílio dos Tribunais de Contas, e o sistema de controle interno de cada Poder e do Ministério Público, fiscalizarão o cumprimento das normas desta Lei Complementar, com ênfase no que se refere a I. atingimento das metas estabelecidas na lei de diretrizes orçamentárias. II. limites e condições para realização de operações de crédito e inscrição em Restos a Pagar. III. destinação de recursos obtidos com a alienação de ativos, tendo em vista as restrições constitucionais e as desta Lei Complementar. IV. cumprimento do limite de gastos totais dos legislativos municipais, quando houver.','[["A","Apenas I e II."],["B","Apenas III e IV."],["C","Apenas I, II e IV."],["D","Apenas II e III."],["E","I, II, III e IV."]]'::jsonb,'E',2012,662,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Controle da Gestão Fiscal (arts. 56 a 59 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — I, II, III e IV.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Controle da Gestão Fiscal (arts. 56 a 59 da LRF)"}'::jsonb,'Analise as assertivas e assinale a alternativa que aponta as corretas. De acordo com a Lei de Responsabilidade Fiscal, o Poder Legislativo, diretamente ou com o auxílio dos Tribunais de Contas, e o sistema de controle interno de cada Poder e do Ministério Público, fiscalizarão o cumprimento das normas desta Lei Complementar, com ênfase no que se refere a I. atingimento das meta') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3598450',2238,75,'P2','AFO, Direito Financeiro e Contabilidade Pública - Das Transferências Voluntárias (art. 25 da LRF)','FAFIPA - Cont (Pref Franc Beltrão)/Pref Franc Beltrão/2025','Caderno Contabilidade Pública Parte 4','Uma Prefeitura Municipal celebrou, em abril de 2025, um convênio com o Governo Federal no valor total de R$ 600.000,00, destinado à reforma do hospital municipal. O valor foi dividido em três parcelas, condicionadas à execução de etapas físicas previamente estabelecidas no plano de trabalho. A primeira etapa foi concluída em junho de 2025, e a prestação de contas parcial foi aprovada pelo órgão concedente. O valor correspondente (R$ 200.000,00) foi creditado na conta bancária da prefeitura no dia 3 de julho de 2025. Sobre os procedimentos contábeis e orçamentários relacionados a essa situação, analise as afirmativas a seguir. I. Como se trata de uma transferência voluntária, a prefeitura só pode registrar a receita orçamentária no momento da entrada dos recursos em sua conta bancária. II. A prefeitura só poderá utilizar os recursos da transferência após registrá-los como receita orçamentária no momento do ingresso financeiro. III. Mesmo que o convênio esteja assinado, a prefeitura não deve registrar direito a receber, a menos que haja cláusula contratual assegurando o repasse após o cumprimento da etapa. IV. O valor de R$ 200.000,00, ainda que não creditado em conta, já pode ser utilizado orçamentariamente a partir da assinatura do convênio. Está CORRETO o que se afirma em:','[["A","I e II, apenas."],["B","II e IV, apenas."],["C","I, II e III, apenas."],["D","I, II, III e IV."]]'::jsonb,'C',2025,663,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Das Transferências Voluntárias (art. 25 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — I, II e III, apenas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Das Transferências Voluntárias (art. 25 da LRF)"}'::jsonb,'Uma Prefeitura Municipal celebrou, em abril de 2025, um convênio com o Governo Federal no valor total de R$ 600.000,00, destinado à reforma do hospital municipal. O valor foi dividido em três parcelas, condicionadas à execução de etapas físicas previamente estabelecidas no plano de trabalho. A primeira etapa foi concluída em junho de 2025, e a prestação de contas parcial foi ap') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3930602',2239,74,'P2','AFO, Direito Financeiro e Contabilidade Pública - Das Transferências Voluntárias (art. 25 da LRF)','FAFIPA - Proc Jur (IPRECONTENDA)/IPRECONTENDA/2024','Caderno Contabilidade Pública Parte 4','A Lei de Responsabilidade Fiscal trata das condições para a transferência voluntária de recursos entre entes federativos no Brasil, impondo requisitos e restrições para garantir a legalidade e a correta aplicação desses recursos. Considerando as exigências e vedações previstas no artigo 25 dessa lei, assinale a alternativa CORRETA.','[["A","A transferência voluntária de recursos entre entes federativos não exige comprovação de que o beneficiário esteja em dia com tributos e obrigações financeiras com o ente transferidor."],["B","A transferência voluntária só pode ocorrer quando há previsão orçamentária de contrapartida por parte do ente beneficiário, além de outras exigências como o cumprimento dos limites constitucionais para saúde e educação."],["C","As sanções de suspensão de transferências voluntárias aplicam-se também a recursos destinados a ações de educação, saúde e assistência social, sem exceções."],["D","A transferência voluntária de recursos pode ser realizada mesmo que o ente beneficiário não cumpra os limites das dívidas consolidada e mobiliária, desde que esteja regular em relação aos tributos."]]'::jsonb,'B',2024,664,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Das Transferências Voluntárias (art. 25 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — A transferência voluntária só pode ocorrer quando há previsão orçamentária de contrapartida por parte do ente beneficiário, além de outras exigências como o cumprimento dos limites constitucionais para saúde e educação.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Das Transferências Voluntárias (art. 25 da LRF)"}'::jsonb,'A Lei de Responsabilidade Fiscal trata das condições para a transferência voluntária de recursos entre entes federativos no Brasil, impondo requisitos e restrições para garantir a legalidade e a correta aplicação desses recursos. Considerando as exigências e vedações previstas no artigo 25 dessa lei, assinale a alternativa CORRETA.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('917579',2240,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Das Transferências Voluntárias (art. 25 da LRF)','FAFIPA - Ass Leg (CM Toledo)/CM Toledo (PR)/2014','Caderno Contabilidade Pública Parte 4','Nos termos da Lei de Responsabilidade Fiscal (Lei Complementar nº. 101, de 04 de maio de 2000), a entrega de recursos correntes ou de capital a outro ente da Federação, a título de cooperação, auxílio ou assistência financeira, que não decorra de determinação constitucional, legal ou os destinados ao Sistema Único de Saúde, para efeito desta Lei Complementar, entende-se por:','[["A","Transferência voluntária."],["B","Transferência compulsória."],["C","Transferência aleatória."],["D","Transferência Regressiva."]]'::jsonb,'A',2014,665,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Das Transferências Voluntárias (art. 25 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — Transferência voluntária.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Das Transferências Voluntárias (art. 25 da LRF)"}'::jsonb,'Nos termos da Lei de Responsabilidade Fiscal (Lei Complementar nº. 101, de 04 de maio de 2000), a entrega de recursos correntes ou de capital a outro ente da Federação, a título de cooperação, auxílio ou assistência financeira, que não decorra de determinação constitucional, legal ou os destinados ao Sistema Único de Saúde, para efeito desta Lei Complementar, entende-se por:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('1061265',2241,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Das Transferências Voluntárias (art. 25 da LRF)','FAFIPA - AContI (CM Foz do Iguaçu)/CM Foz do Iguaçu/2012','Caderno Contabilidade Pública Parte 4','O que entende-se pela entrega de recursos correntes ou de capital a outro ente da Federação, a título de cooperação, auxílio ou assistência financeira, que não decorra de determinação constitucional, legal ou os destinados ao Sistema Único de Saúde, de acordo com a lei complementar 101/00, art. 25?','[["A","Transferência voluntária."],["B","Destinação de recursos públicos para o setor."],["C","Endividamento do setor público."],["D","Limites das operações de crédito."],["E","Antecipação da despesa orçamentária."]]'::jsonb,'A',2012,666,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Das Transferências Voluntárias (art. 25 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — Transferência voluntária.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Das Transferências Voluntárias (art. 25 da LRF)"}'::jsonb,'O que entende-se pela entrega de recursos correntes ou de capital a outro ente da Federação, a título de cooperação, auxílio ou assistência financeira, que não decorra de determinação constitucional, legal ou os destinados ao Sistema Único de Saúde, de acordo com a lei complementar 101/00, art. 25?') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3876875',2242,86,'P1','AFO, Direito Financeiro e Contabilidade Pública - Introdução às DCASP (Parte V, Capítulo 1 do MCASP e NBC TSP 11)','FAFIPA - Cont (COMESP)/COMESP/2026','Caderno Contabilidade Pública Parte 4','Preencha as lacunas a seguir e assinale a alternativa com a sequência CORRETA. De acordo com o MCASP – 11ª Edição (2024), as Demonstrações Contábeis Aplicadas ao Setor Público (DCASP) são um conjunto de relatórios padronizados que visam evidenciar a situação __________, __________ e __________ das entidades públicas, em atendimento às normas técnicas e à legislação vigente.','[["A","contábil, gerencial e de custos"],["B","patrimonial, financeira e de desempenho"],["C","patrimonial, orçamentária e operacional"],["D","fiscal, financeira e de desempenho"],["E","orçamentária, econômica e de liquidez"]]'::jsonb,'B',2026,667,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Introdução às DCASP (Parte V, Capítulo 1 do MCASP e NBC TSP 11).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — patrimonial, financeira e de desempenho","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Introdução às DCASP (Parte V, Capítulo 1 do MCASP e NBC TSP 11)"}'::jsonb,'Preencha as lacunas a seguir e assinale a alternativa com a sequência CORRETA. De acordo com o MCASP – 11ª Edição (2024), as Demonstrações Contábeis Aplicadas ao Setor Público (DCASP) são um conjunto de relatórios padronizados que visam evidenciar a situação __________, __________ e __________ das entidades públicas, em atendimento às normas técnicas e à legislação vigente.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('2156870',2243,83,'P1','AFO, Direito Financeiro e Contabilidade Pública - Introdução às DCASP (Parte V, Capítulo 1 do MCASP e NBC TSP 11)','FAFIPA - AFis (Pref Ivinhema)/Pref Ivinhema/2022','Caderno Contabilidade Pública Parte 4','Considerando a Lei N.º 4.320/1964, que estabelece as normas para a elaboração de demonstrativos contábeis dos Municípios, a NBC TSP 11 - Apresentação das Demonstrações Contábeis e o Manual de Contabilidade Aplicado ao Setor Público (MCASP), compõem o conjunto de Demonstrações Contábeis Aplicadas ao Setor Público (DCASP):','[["A","Balanço Patrimonial, Demonstração das Variações Patrimoniais, Demonstração das Mutações do Patrimônio Líquido, Demonstração das Origens e Aplicações de Recursos, Balanço Orçamentário, Balanço Financeiro e Notas Explicativas."],["B","Balanço Patrimonial, Demonstração das Variações Patrimoniais, Demonstração das Mutações do Patrimônio Líquido, Demonstração dos Fluxos de Caixa, Balanço Orçamentário, Balanço Financeiro e Notas Explicativas."],["C","Balanço Patrimonial, Demonstração dos Lucros ou Prejuízos Acumulados, Demonstração do Resultado Abrangente, Demonstração dos Fluxos de Caixa, Balanço Orçamentário, Balanço Financeiro e Notas Explicativas."],["D","Balanço Patrimonial, Demonstração das Mutações do Patrimônio Líquido, Demonstração das Origens e Aplicações de Recursos, Demonstração dos Fluxos de Caixa, Balanço Orçamentário, Balanço Financeiro e Notas Explicativas."],["E","Balanço Patrimonial, Demonstração do Resultado, Demonstração do Valor Adicionado, Demonstração dos Fluxos de Caixa, Balanço Orçamentário, Balanço Financeiro e Notas Explicativas."]]'::jsonb,'B',2022,668,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Introdução às DCASP (Parte V, Capítulo 1 do MCASP e NBC TSP 11).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — Balanço Patrimonial, Demonstração das Variações Patrimoniais, Demonstração das Mutações do Patrimônio Líquido, Demonstração dos Fluxos de Caixa, Balanço Orçamentário, Balanço Financeiro e Notas Explicativas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Introdução às DCASP (Parte V, Capítulo 1 do MCASP e NBC TSP 11)"}'::jsonb,'Considerando a Lei N.º 4.320/1964, que estabelece as normas para a elaboração de demonstrativos contábeis dos Municípios, a NBC TSP 11 - Apresentação das Demonstrações Contábeis e o Manual de Contabilidade Aplicado ao Setor Público (MCASP), compõem o conjunto de Demonstrações Contábeis Aplicadas ao Setor Público (DCASP):') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('1972643',2244,82,'P1','AFO, Direito Financeiro e Contabilidade Pública - Introdução às DCASP (Parte V, Capítulo 1 do MCASP e NBC TSP 11)','FAFIPA - Cont (CM Marumbi)/CM Marumbi/2020','Caderno Contabilidade Pública Parte 4','Segundo a NBC TSP 11, são Demonstrações Contábeis Aplicadas ao Setor Público (DCASP), EXCETO:','[["A","Demonstração das Mutações do Patrimônio Líquido."],["B","Demonstração dos Fluxos de Caixa."],["C","Demonstração do Valor Adicionado."],["D","Balanço Patrimonial."]]'::jsonb,'C',2020,669,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Introdução às DCASP (Parte V, Capítulo 1 do MCASP e NBC TSP 11).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — Demonstração do Valor Adicionado.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Introdução às DCASP (Parte V, Capítulo 1 do MCASP e NBC TSP 11)"}'::jsonb,'Segundo a NBC TSP 11, são Demonstrações Contábeis Aplicadas ao Setor Público (DCASP), EXCETO:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCL