INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('942375',2245,82,'P1','AFO, Direito Financeiro e Contabilidade Pública - Introdução às DCASP (Parte V, Capítulo 1 do MCASP e NBC TSP 11)','FAFIPA - Cont (CIPS)/CIPS/2013','Caderno Contabilidade Pública Parte 4','Considerando a necessidade de promover a convergência das práticas contábeis vigentes no setor público com as normas internacionais de contabilidade e a necessidade de elaboração e publicação de demonstrações contábeis consolidadas e padronizadas para todos os entes, por meio da Portaria nº 438, de 12 de Julho de 2012, o Tesouro Nacional resolve excluir da Lei nº 4.320, de 17 de março de 1964:','[["A","O Balanço Orçamentário."],["B","O Balanço Financeiro."],["C","A Demonstração das Variações Patrimoniais."],["D","A Demonstração dos Fluxos de Caixa."],["E","A Demonstração do Resultado Econômico."]]'::jsonb,'E',2013,670,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Introdução às DCASP (Parte V, Capítulo 1 do MCASP e NBC TSP 11).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — A Demonstração do Resultado Econômico.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Introdução às DCASP (Parte V, Capítulo 1 do MCASP e NBC TSP 11)"}'::jsonb,'Considerando a necessidade de promover a convergência das práticas contábeis vigentes no setor público com as normas internacionais de contabilidade e a necessidade de elaboração e publicação de demonstrações contábeis consolidadas e padronizadas para todos os entes, por meio da Portaria nº 438, de 12 de Julho de 2012, o Tesouro Nacional resolve excluir da Lei nº 4.320, de 17 d') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3936164',2246,86,'P1','AFO, Direito Financeiro e Contabilidade Pública - Provisões, Passivos e Ativos Contingentes (MCASP e NBC TSP 03)','FAFIPA - PSP (SESA PR)/SESA PR/Contador/2026','Caderno Contabilidade Pública Parte 4','A Diretoria Financeira da Secretaria de Estado da Saúde analisa o tratamento contábil de três situações jurídicas apontadas pela Procuradoria Geral do Estado: I. Uma empresa fornecedora de medicamentos move ação indenizatória contra a Secretaria de Estado da Saúde. A assessoria jurídica classifica a probabilidade de perda como remota, pois a jurisprudência é pacificada a favor do Estado neste tipo de demanda. II. Um ex-servidor obteve sentença judicial definitiva (transitada em julgado) condenando o Estado ao pagamento de verbas salariais. O valor é exato e o pagamento ocorrerá via Requisição de Pequeno Valor (RPV) em até 90 dias. III. Há uma ação de reparação civil por acidente com ambulância da rede estadual. A probabilidade de condenação é provável e existe estimativa confiável do valor, com desembolso previsto para daqui a 24 meses. De acordo com a NBC TSP 03 - Provisões, Passivos Contingentes e Ativos Contingentes, a CORRETA classificação ou tratamento contábil dessas situações, na ordem I, II e III, respectivamente, é como:','[["A","Passivo Circulante; Provisão (circulante); Passivo Contingente (de divulgação facultativa em Notas Explicativas)."],["B","Provisão; Passivo Contingente (não circulante); Passivo Circulante."],["C","Passivo Contingente (de divulgação facultativa em Notas Explicativas); Passivo Circulante; Provisão (não circulante)."],["D","Passivo Contingente (de divulgação obrigatória em Notas Explicativas); Provisão; Passivo Contingente (não circulante)."],["E","Provisão (circulante); Provisão (não circulante); Passivo Não Circulante."]]'::jsonb,'C',2026,671,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Provisões, Passivos e Ativos Contingentes (MCASP e NBC TSP 03).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — Passivo Contingente (de divulgação facultativa em Notas Explicativas); Passivo Circulante; Provisão (não circulante).","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Provisões, Passivos e Ativos Contingentes (MCASP e NBC TSP 03)"}'::jsonb,'A Diretoria Financeira da Secretaria de Estado da Saúde analisa o tratamento contábil de três situações jurídicas apontadas pela Procuradoria Geral do Estado: I. Uma empresa fornecedora de medicamentos move ação indenizatória contra a Secretaria de Estado da Saúde. A assessoria jurídica classifica a probabilidade de perda como remota, pois a jurisprudência é pacificada a favor ') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3599095',2247,85,'P1','AFO, Direito Financeiro e Contabilidade Pública - Provisões, Passivos e Ativos Contingentes (MCASP e NBC TSP 03)','FAFIPA - Cont (CICA)/CICA/2025','Caderno Contabilidade Pública Parte 4','A normatização dos procedimentos contábeis relativos a provisões, aos passivos contingentes e aos ativos contingentes foi elaborada com base na Norma Brasileira de Contabilidade (NBC TSP) 03 - Provisões, Passivos Contingentes e Ativos Contingentes do Conselho Federal de Contabilidade. O Plano de Contas Aplicado ao Setor Público (PCASP) elenca alguns tipos de provisões, EXCETO:','[["A","provisões para riscos trabalhistas."],["B","provisões para riscos fiscais"],["C","provisões para riscos cíveis."],["D","provisões para créditos de liquidação duvidosa."]]'::jsonb,'D',2025,672,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Provisões, Passivos e Ativos Contingentes (MCASP e NBC TSP 03).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — provisões para créditos de liquidação duvidosa.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Provisões, Passivos e Ativos Contingentes (MCASP e NBC TSP 03)"}'::jsonb,'A normatização dos procedimentos contábeis relativos a provisões, aos passivos contingentes e aos ativos contingentes foi elaborada com base na Norma Brasileira de Contabilidade (NBC TSP) 03 - Provisões, Passivos Contingentes e Ativos Contingentes do Conselho Federal de Contabilidade. O Plano de Contas Aplicado ao Setor Público (PCASP) elenca alguns tipos de provisões, EXCETO:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3680446',2248,83,'P1','AFO, Direito Financeiro e Contabilidade Pública - Provisões, Passivos e Ativos Contingentes (MCASP e NBC TSP 03)','FAFIPA - Cont (CM SJ Pinhais)/CM SJ dos Pinhais/2023','Caderno Contabilidade Pública Parte 4','Com fulcro na Norma Brasileira de Contabilidade Aplicada ao Setor Público NBC TSP 03 - Provisões, Passivos Contingentes e Ativos Contingentes, analise as assertivas a seguir. I. As provisões podem ser diferenciadas de outros passivos devido à incerteza acerca do prazo ou do valor do desembolso futuro necessário para a sua liquidação. II. A provisão deve ser reconhecida, ainda que não exista uma obrigação presente na data das demonstrações contábeis. III. A apropriação mensal por competência de encargos relativos a férias e 13º salário dos empregados é um exemplo típico de provisão, devendo ser reconhecida como tal no Balanço Patrimonial. Está CORRETO que se afirma em:','[["A","Apenas I."],["B","Apenas I e III."],["C","Apenas I e II."],["D","Apenas II e III."],["E","I, II e III."]]'::jsonb,'A',2023,673,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Provisões, Passivos e Ativos Contingentes (MCASP e NBC TSP 03).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — Apenas I.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Provisões, Passivos e Ativos Contingentes (MCASP e NBC TSP 03)"}'::jsonb,'Com fulcro na Norma Brasileira de Contabilidade Aplicada ao Setor Público NBC TSP 03 - Provisões, Passivos Contingentes e Ativos Contingentes, analise as assertivas a seguir. I. As provisões podem ser diferenciadas de outros passivos devido à incerteza acerca do prazo ou do valor do desembolso futuro necessário para a sua liquidação. II. A provisão deve ser reconhecida, ainda q') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('1336841',2249,82,'P1','AFO, Direito Financeiro e Contabilidade Pública - Provisões, Passivos e Ativos Contingentes (MCASP e NBC TSP 03)','FAFIPA - Cont Jr (FOZTRANS)/FOZTRANS/2019','Caderno Contabilidade Pública Parte 4','O Passivo Contingente é uma obrigação possível resultante de eventos passados e cuja existência será confirmada apenas pela ocorrência ou não de um ou mais eventos futuros incertos que não estão totalmente sob o controle da entidade. Assim, de acordo com o MCASP, os passivos contingentes são registrados em contas:','[["A","Financeiras."],["B","Patrimoniais."],["C","De resultado."],["D","Orçamentárias."],["E","De controle."]]'::jsonb,'E',2019,674,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Provisões, Passivos e Ativos Contingentes (MCASP e NBC TSP 03).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — De controle.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Provisões, Passivos e Ativos Contingentes (MCASP e NBC TSP 03)"}'::jsonb,'O Passivo Contingente é uma obrigação possível resultante de eventos passados e cuja existência será confirmada apenas pela ocorrência ou não de um ou mais eventos futuros incertos que não estão totalmente sob o controle da entidade. Assim, de acordo com o MCASP, os passivos contingentes são registrados em contas:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3082566',2250,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Normas Municipais sobre Direito Financeiro e Contabilidade Pública','FAFIPA - Cont (Londrina)/Pref Londrina/Serviços de Contabilidade/2015','Caderno Contabilidade Pública Parte 4','As regras para a fiscalização contábil, financeira e orçamentária prevista na Lei Orgânica do Município de Londrina/PR estão descritas na Seção X: As contas do Município ficarão à disposição dos contribuintes, na Câmara Municipal, durante 360 (trezentos e sessenta) dias, a partir de 15 de junho de cada exercício, para exame e apreciação. Certo Errado','[]'::jsonb,'E',2015,675,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Normas Municipais sobre Direito Financeiro e Contabilidade Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — conforme o gabarito registrado no caderno.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Normas Municipais sobre Direito Financeiro e Contabilidade Pública"}'::jsonb,'As regras para a fiscalização contábil, financeira e orçamentária prevista na Lei Orgânica do Município de Londrina/PR estão descritas na Seção X: As contas do Município ficarão à disposição dos contribuintes, na Câmara Municipal, durante 360 (trezentos e sessenta) dias, a partir de 15 de junho de cada exercício, para exame e apreciação. Certo Errado') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('923199',2251,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Normas Municipais sobre Direito Financeiro e Contabilidade Pública','FAFIPA - AnLg (CM Campina GS)/CM Campina G do Sul/2014','Caderno Contabilidade Pública Parte 4','A respeito do Orçamento Municipal, assinale a alternativa CORRETA:','[["A","Publicado o Parecer da Comissão de Finanças e Orçamento, será o projeto de leido Plano Plurianual imediatamente encaminhado à Mesa, que o fará constar da pauta da Ordem do Dia das duas sessões ordinárias subsequentes, para recebimento de emendas."],["B","Recebido o projeto de lei das Diretrizes Orçamentárias, será ele distribuído em cópias aos Vereadores e remetido imediatamente à Comissão de Finanças e Orçamento, para em dez dias emitir parecer."],["C","Compete privativamente ao Presidente da Câmara de Vereadores enviar à Mesa o plano plurianual, as diretrizes orçamentárias e o orçamento anual do Município."],["D","Compete especificamente à Comissão de Finanças e Orçamento, emitir parecer somente e exclusivamente sobre a Lei de Diretrizes Orçamentárias e o Plano Plurianual do Município."]]'::jsonb,'B',2014,676,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Normas Municipais sobre Direito Financeiro e Contabilidade Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — Recebido o projeto de lei das Diretrizes Orçamentárias, será ele distribuído em cópias aos Vereadores e remetido imediatamente à Comissão de Finanças e Orçamento, para em dez dias emitir parecer.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Normas Municipais sobre Direito Financeiro e Contabilidade Pública"}'::jsonb,'A respeito do Orçamento Municipal, assinale a alternativa CORRETA:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('923515',2252,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Normas Municipais sobre Direito Financeiro e Contabilidade Pública','FAFIPA - OfAd (CM Campina GS)/CM Campina G do Sul/2014','Caderno Contabilidade Pública Parte 4','A Lei Orçamentária Anual-LOA compreende, EXCETO:','[["A","O orçamento fiscal, fixando as despesas referentes aos órgãos e entidades da administração direta e indireta, instituídos e mantidos pelo Poder Público Municipal, estimando as receitas do Tesouro Municipal."],["B","A LOA é elaborada pelos Poderes Executivo e Legislativo e pela população, por meio de audiências públicas."],["C","O orçamento de investimentos das empresas em que o Município, direta ou indiretamente, detenha a maioria do capital social com direito a voto."],["D","As receitas que são descritas na LOA podem ser classificadas como receitas correntes, aquelas relacionadas à contratação de empréstimos, e receitas de capital, aquelas relacionadas à arrecadação de impostos e taxas."]]'::jsonb,'D',2014,677,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Normas Municipais sobre Direito Financeiro e Contabilidade Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — As receitas que são descritas na LOA podem ser classificadas como receitas correntes, aquelas relacionadas à contratação de empréstimos, e receitas de capital, aquelas relacionadas à arrecadação de impostos e taxas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Normas Municipais sobre Direito Financeiro e Contabilidade Pública"}'::jsonb,'A Lei Orçamentária Anual-LOA compreende, EXCETO:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('1061262',2253,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Normas Municipais sobre Direito Financeiro e Contabilidade Pública','FAFIPA - AContI (CM Foz do Iguaçu)/CM Foz do Iguaçu/2012','Caderno Contabilidade Pública Parte 4','Qual será o prazo para a homologação, a contar da ocorrência do fato gerador? Assinale a alternativa correta, segundo a lei complementar municipal n.82/03 art. 57.','[["A","2 (dois) anos."],["B","3 (três) anos."],["C","4 (quatro) anos."],["D","5 (cinco) anos."],["E","6 (seis) anos."]]'::jsonb,'D',2012,678,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Normas Municipais sobre Direito Financeiro e Contabilidade Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — 5 (cinco) anos.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Normas Municipais sobre Direito Financeiro e Contabilidade Pública"}'::jsonb,'Qual será o prazo para a homologação, a contar da ocorrência do fato gerador? Assinale a alternativa correta, segundo a lei complementar municipal n.82/03 art. 57.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3598401',2254,75,'P2','AFO, Direito Financeiro e Contabilidade Pública - Dívida Ativa','FAFIPA - Cont (Pref Franc Beltrão)/Pref Franc Beltrão/2025','Caderno Contabilidade Pública Parte 4','O contador de uma Prefeitura Municipal identificou que diversos contribuintes não quitaram o Imposto Predial e Territorial Urbano (IPTU) no encerramento do exercício de 2024, mesmo após o prazo legal e as tentativas de cobrança administrativa. Diante disso, determinou a inscrição desses débitos como dívida ativa tributária. Com base no Manual de Contabilidade Aplicada ao Setor Público (MCASP − 10ª edição) e na Lei Federal nº 4.320/1964, é CORRETO afirmar que o registro da inscrição em dívida ativa:','[["A","só pode ser contabilizado como receita quando houver efetivo pagamento, sendo vedado seu registro antes da arrecadação, por contrariar o regime de caixa da contabilidade pública."],["B","gera uma variação patrimonial aumentativa no ente como um todo, pois passa a constituir um direito a receber líquido e certo."],["C","deve ser registrado no passivo, por representar uma obrigação de cobrança judicial do ente frente aos contribuintes inadimplentes."],["D","representa um fato contábil permutativo, pois ocorre apenas a substituição de um crédito a receber por outro de maior risco de realização, sem alterar o patrimônio líquido."]]'::jsonb,'D',2025,679,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Dívida Ativa.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — representa um fato contábil permutativo, pois ocorre apenas a substituição de um crédito a receber por outro de maior risco de realização, sem alterar o patrimônio líquido.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Dívida Ativa"}'::jsonb,'O contador de uma Prefeitura Municipal identificou que diversos contribuintes não quitaram o Imposto Predial e Territorial Urbano (IPTU) no encerramento do exercício de 2024, mesmo após o prazo legal e as tentativas de cobrança administrativa. Diante disso, determinou a inscrição desses débitos como dívida ativa tributária. Com base no Manual de Contabilidade Aplicada ao Setor ') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3862383',2255,75,'P2','AFO, Direito Financeiro e Contabilidade Pública - Dívida Ativa','FAFIPA - Cont (Pref Jundiaí do Sul)/Pref Jundiaí do Sul/2025','Caderno Contabilidade Pública Parte 4','Assinale a alternativa que preenche CORRETAMENTE a lacuna a seguir. A ___________ é o conjunto de créditos tributários e não tributários em favor da Fazenda Pública, não recebidos no prazo para pagamento definido em lei ou em decisão proferida em processo regular, inscrito pelo órgão ou entidade competente, após apuração de certeza e liquidez.','[["A","Receita de Dívida Ativa"],["B","Receita de Sonegação"],["C","Receita de Arrecadação posterior ao fato gerador"],["D","Receita de Multas Compensatórias"],["E","Receita de Suprimento de Fundos"]]'::jsonb,'A',2025,680,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Dívida Ativa.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — Receita de Dívida Ativa","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Dívida Ativa"}'::jsonb,'Assinale a alternativa que preenche CORRETAMENTE a lacuna a seguir. A ___________ é o conjunto de créditos tributários e não tributários em favor da Fazenda Pública, não recebidos no prazo para pagamento definido em lei ou em decisão proferida em processo regular, inscrito pelo órgão ou entidade competente, após apuração de certeza e liquidez.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('1058748',2256,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Dívida Ativa','FAFIPA - Cont Jr (FC Foz)/FC Foz do Iguaçu/2019','Caderno Contabilidade Pública Parte 4','Nos termos da Lei nº 4.320/64, os créditos da dívida ativa exigíveis pelo transcurso do prazo para pagamento, serão inscritos, na forma da legislação própria, como Dívida Ativa, em registro próprio, após apurada a sua liquidez e certeza, e a respectiva receita será escriturada a esse título. Quanto à sua classificação, os créditos da dívida ativa dividem-se em naturezas:','[["A","Orçamentária e Financeira."],["B","Patrimonial e Extrapatrimonial."],["C","Tributária e não tributária."],["D","Orçamentária e de Controle."]]'::jsonb,'C',2019,681,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Dívida Ativa.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — Tributária e não tributária.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Dívida Ativa"}'::jsonb,'Nos termos da Lei nº 4.320/64, os créditos da dívida ativa exigíveis pelo transcurso do prazo para pagamento, serão inscritos, na forma da legislação própria, como Dívida Ativa, em registro próprio, após apurada a sua liquidez e certeza, e a respectiva receita será escriturada a esse título. Quanto à sua classificação, os créditos da dívida ativa dividem-se em naturezas:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3598394',2257,75,'P2','AFO, Direito Financeiro e Contabilidade Pública - Despesas de Exercícios Anteriores (DEA)','FAFIPA - Cont (Pref Franc Beltrão)/Pref Franc Beltrão/2025','Caderno Contabilidade Pública Parte 4','A equipe de contabilidade de uma Prefeitura Municipal identificou, em junho de 2025, a solicitação de pagamento referente ao fornecimento de materiais escolares entregues regularmente em fevereiro de 2024. No entanto, por falha administrativa, a despesa não foi empenhada no exercício de 2024. A Secretaria Municipal de Educação apresentou a nota fiscal original, comprovação de recebimento dos produtos, a identificação do credor e a justificativa pela qual a despesa não foi empenhada ou paga na época própria. Com base nas normas de contabilidade aplicadas ao setor público, é CORRETO afirmar que esse pagamento:','[["A","só poderá ser quitado após a abertura de crédito especial, uma vez que não há previsão legal para pagamento de despesas de exercícios anteriores não empenhadas."],["B","não pode ser realizado, pois a despesa não foi empenhada em 2024 nem inscrita em restos a pagar, devendo ser arquivada por decurso de prazo."],["C","pode ser pago como despesa de exercício anterior (2024), desde que seja reconhecido como tal e haja dotação orçamentária específica para essa finalidade."],["D","deve ser obrigatoriamente inscrito como restos a pagar não processado, com posterior liquidação, para possibilitar o pagamento no exercício de 2025."]]'::jsonb,'C',2025,682,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Despesas de Exercícios Anteriores (DEA).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — pode ser pago como despesa de exercício anterior (2024), desde que seja reconhecido como tal e haja dotação orçamentária específica para essa finalidade.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Despesas de Exercícios Anteriores (DEA)"}'::jsonb,'A equipe de contabilidade de uma Prefeitura Municipal identificou, em junho de 2025, a solicitação de pagamento referente ao fornecimento de materiais escolares entregues regularmente em fevereiro de 2024. No entanto, por falha administrativa, a despesa não foi empenhada no exercício de 2024. A Secretaria Municipal de Educação apresentou a nota fiscal original, comprovação de r') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3598426',2258,75,'P2','AFO, Direito Financeiro e Contabilidade Pública - Despesas de Exercícios Anteriores (DEA)','FAFIPA - Cont (Pref Franc Beltrão)/Pref Franc Beltrão/2025','Caderno Contabilidade Pública Parte 4','Uma Prefeitura Municipal está organizando a execução orçamentária do exercício de 2025. Durante esse processo, foram identificadas obrigações pendentes relativas a anos anteriores, entre elas: - Fornecimento de gêneros alimentícios em dezembro de 2023, com nota fiscal entregue e aceita pelo almoxarifado, mas cujo empenho foi anulado no encerramento do exercício. - Cancelamento indevido de Restos a Pagar processados em 2022, com posterior requerimento judicial do fornecedor. - Despesa com revisão de plano de carreira de servidores reconhecida apenas após decisão normativa publicada em janeiro de 2025, mas com efeitos retroativos a agosto de 2024. - Pagamento de multa de contrato administrativo firmado em 2021, cuja obrigação foi reconhecida somente após parecer jurídico emitido em abril de 2025. Com base nessas situações, assinale a alternativa INCORRETA sobre o tratamento orçamentário e patrimonial das Despesas de Exercícios Anteriores.','[["A","A aquisição de gêneros alimentícios com entrega realizada em 2023, mas empenho anulado, configura Despesa de Exercício Anterior com fato gerador ocorrido no exercício anterior e deve gerar, no exercício atual, reconhecimento de passivo e de Variação Patrimonial Diminutiva (VPD)."],["B","O pagamento de despesa relativa à revisão do plano de carreira dos servidores com efeitos retroativos a 2024 deve ser tratado como Despesa de Exercício Anterior e registrado patrimonialmente como ajuste de exercícios anteriores no patrimônio líquido."],["C","A multa contratual de 2021, cuja obrigação foi reconhecida apenas em 2025, deve ser executada como Despesa de Exercício Anterior, e, se o fato gerador foi no exercício atual, deve gerar apenas registro de Variação Patrimonial Diminutiva (VPD) no próprio exercício."],["D","Restos a Pagar processados com prescrição interrompida, reconhecidos judicialmente, não geram nova Variação Patrimonial Diminutiva (VPD) no exercício da execução, pois já foram reconhecidos no exercício original."]]'::jsonb,'B',2025,683,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Despesas de Exercícios Anteriores (DEA).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — O pagamento de despesa relativa à revisão do plano de carreira dos servidores com efeitos retroativos a 2024 deve ser tratado como Despesa de Exercício Anterior e registrado patrimonialmente como ajuste de exercícios anteriores no patrimônio líquido.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Despesas de Exercícios Anteriores (DEA)"}'::jsonb,'Uma Prefeitura Municipal está organizando a execução orçamentária do exercício de 2025. Durante esse processo, foram identificadas obrigações pendentes relativas a anos anteriores, entre elas: - Fornecimento de gêneros alimentícios em dezembro de 2023, com nota fiscal entregue e aceita pelo almoxarifado, mas cujo empenho foi anulado no encerramento do exercício. - Cancelamento ') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
